import sys,os
sys.path.append(os.path.abspath(os.path.dirname(__file__) + '/' + '..'))


import math
from typing import Dict, Any, List
from elasticsearch import Elasticsearch, exceptions
from pprint import pprint
from config.config import AI_HOST, AI_USERNAME, AI_PASSWORD, AI_PORT
from util.time_util import calculate_execution_time

class ElasticSearchClient:
    """Class to interact with Elasticsearch to retrieve and process data.

    This class provides methods to perform Elasticsearch operations, including querying,
    calculating custom scores, and fetching top words based on the match query.

    Attributes:
        es (Elasticsearch): Elasticsearch client instance.
        index (str): The index to search in.
    """

    def __init__(self, host: str, username: str, password: str, port: int, index: str):
        """Initializes the Elasticsearch client and checks if the connection is successful.

        Args:
            host (str): Elasticsearch host.
            username (str): Elasticsearch username for authentication.
            password (str): Elasticsearch password for authentication.
            port (int): Port number for Elasticsearch.
            index (str): The index in Elasticsearch to query.
        """
        try:
            self.es = Elasticsearch(
                hosts=host,
                http_auth=(username, password),
                port=port
            )
            self.index = index
            # Ping to check if the connection is successful
            if not self.es.ping():
                raise ConnectionError("Failed to connect to Elasticsearch!")
            print("Successfully connected to Elasticsearch!")
        except exceptions.ElasticsearchException as e:
            print(f"Error initializing Elasticsearch client: {e}")
            raise  # Re-raise the exception after logging

    def search_knowledge(self, knowledge_base_id: str) -> List[Dict[str, Any]]:
        query_body = {
            "query": {
                "bool": {
                    "must": [
                        {
                            "match": {
                                "knowledgeBaseId": knowledge_base_id
                            }
                        }
                    ]
                }
            }
        }
        response = self.es.search(index=self.index, body=query_body)
        return response['hits']['hits']

    def search_by_query(self, query_text: str, knowledge_base_id: str = None, size: int = 100) -> List[Dict[str, Any]]:
        """Searches for documents that match the query text in the nodeName field.

        Args:
            query_text (str): The query text to search for.
            knowledge_base_id (str, optional): The knowledge base ID to filter by. Defaults to None.
            size (int, optional): The number of results to return. Defaults to 100.

        Returns:
            List[Dict[str, Any]]: A list of Elasticsearch search hits.
        """
        try:
            es_body = {
                "query": {
                    "bool": {
                        "must": [
                            {
                                "match": {
                                    "nodeName": query_text,  # Match query for nodeName field

                                }
                            }
                        ],
                        # "should": [
                        #     {
                        #         "terms": {
                        #             "nodeKeyWordList": query_text  # Term query for nodeKeyWordList element matching
                        #         }
                        #     }
                        # ],
                        # "minimum_should_match": 1  # Ensure that at least one of the conditions should match
                    }
                },
                "size": size,
                "sort": [
                    {
                        "_score": {
                            "order": "desc"
                        }
                    }
                ]
            }

            if knowledge_base_id:
                # Add filter for knowledgeBaseId if provided
                es_body["query"]["bool"]["filter"] = [
                    {
                        "term": {
                            "knowledgeBaseId": knowledge_base_id
                        }
                    }
                ]

            response = self.es.search(index=self.index, body=es_body)
            return response['hits']['hits']

        except exceptions.NotFoundError:
            print("Index not found!")
            return []
        except exceptions.ConnectionError as e:
            print(f"Connection error: {e}")
            return []
        except Exception as e:
            print(f"Error during search query execution: {e}")
            return []

    def calculate_score(self, score: float, node_name: str, node_level: int) -> float:
        """Calculates the final score based on the custom formula.

        Args:
            score (float): The original score returned by Elasticsearch's match query.
            node_name (str): The node name to calculate the score for.
            node_level (int): The level of the node to adjust the score.

        Returns:
            float: The final custom score.
        """
        try:
            node_length = len(node_name)
            # Calculate the adjusted score based on the formula
            final_score = score * math.sqrt(node_level / node_length)
            return final_score
        except ZeroDivisionError:
            print(f"Error: Division by zero when calculating score for node: {node_name}")
            return 0.0
        except Exception as e:
            print(f"Error calculating score: {e}")
            return 0.0

    @calculate_execution_time("ElasticSearchClient.get_top_hits")
    def get_top_hits(self, query_text: str, knowledge_base_id: str = None, size: int = 10) -> List[Dict[str, Any]]:
        """Fetches the top hits based on the custom scoring mechanism.

        Args:
            query_text (str): The query text to search for.
            knowledge_base_id (str, optional): The knowledge base ID to filter by. Defaults to None.
            size (int, optional): The number of results to return. Defaults to 100.

        Returns:
            List[Dict[str, Any]]: A list of top search hits based on custom scoring.
        """
        query_text = query_text.strip()
        # query_text_set = set(query_text)
        hits = self.search_by_query(query_text, knowledge_base_id, size)
        # # First, analyze the query_text to get the tokenized words
        # query_tokens = self.analyze_text(query_text)
        for hit in hits:
            node_name = hit['_source']['nodeName']
            # node_name_set = set(node_name)
            node_level = hit['_source']['nodeLevel'] + 1
            related_tree_node_list = [relatedTreeNode['nodeName'] for relatedTreeNode in hit['_source']['relatedTreeNodeList']]
            node_key_word_list = hit['_source']['nodeKeyWordList'] + related_tree_node_list
            score = hit['_score']

            # # Extract tokens from nodeName
            # node_tokens = self.analyze_text(node_name)
            # # Find matching tokens with length >= 4
            # matching_tokens = [token for token in query_tokens if token in node_tokens and len(token) >= 4]
            # # If there are matching tokens of length >= 4, we can process them further
            # if matching_tokens:
            #     print(f"Matching tokens (length >= 4) in nodeName: {matching_tokens}")

            custom_score = self.calculate_score(score, node_name, node_level) # * self.jaccard_similarity_sets(query_text_set, node_name_set)
            if (query_text == node_name) or (query_text in node_key_word_list) or (self.is_node_in_query(node_key_word_list, query_text)):
                custom_score = custom_score * 6
            elif (query_text in node_name) or (node_name in query_text):
                custom_score = custom_score * 3
            hit['_score'] = custom_score  # Override Elasticsearch's default score with custom score
        # Sort hits by custom score in descending order
        sorted_hits = sorted(hits, key=lambda x: x['_score'], reverse=True)
        return sorted_hits[:size]

    @staticmethod
    def is_node_in_query(node_key_word_list, query_text: str) -> bool:
        for key_word in node_key_word_list:
            if key_word in query_text:
                return True

    @staticmethod
    def wrap_hits(hits):
        ret_list = []
        for hit in hits:
            ret = {}
            ret['nodeName'] = hit['_source']['nodeName']
            ret['children'] = [relatedTreeNode['nodeName'] for relatedTreeNode in hit['_source']['relatedTreeNodeList'] if relatedTreeNode['type'] == 'children']
            ret['parent'] = [relatedTreeNode['nodeName'] for relatedTreeNode in hit['_source']['relatedTreeNodeList'] if relatedTreeNode['type'] == 'parent']
            ret_list.append(ret)

        return ret_list

    @staticmethod
    def jaccard_similarity_sets(set1: set, set2: set) -> float:
        """
        Calculate the Jaccard Similarity between two sets.

        Args:
            set1 (set): First input set.
            set2 (set): Second input set.

        Returns:
            float: Jaccard similarity score between 0 and 1.
        """
        # Calculate the intersection and union of the two sets
        intersection = set1.intersection(set2)
        union = set1.union(set2)
        # Return the Jaccard similarity score
        return len(intersection) / len(union) if union else 0.0

if __name__ == "__main__":
    try:
        # Initialize the client with the required parameters
        es_client = ElasticSearchClient(
